        "historicalAndCulturalContext": "本文选自《洛杉矶时报》（Los Angeles Times）科学专栏。在整个20世纪，伴随现代工业社会的飞速发展，全球发达国家的人口平均身高经历了一场壮丽的代际增长飞跃——这一由营养改善、传染病控制以及公共卫生系统建立所驱动的身高跨代持续增长现象，在体质人类学与公共卫生领域被称为著名的‘长期趋势’（Secular Trend in Height）。在普通大众甚至职业体育界的感性直觉中，人们常误以为随着时代推移，人类会永无止境地越长越高（NBA赛场上7英尺长人从60年代的3人飙升至42人强化了这种神话）。然而，美国疾病控制与预防中心（CDC）的权威流行病学生长监测数据却揭示了一个出人意料的转折：美国本土世居人群的平均身高早在1960年代初（男性5英尺9英寸，女性5英尺4英寸）就已彻底停滞，标志着人类身高增长已正式撞上了生物学天花板。",
