        "historicalBackground": "1776年《独立宣言》庄严宣告‘人人生而平等’（all men are created equal），享有不可剥夺的生命、自由与追求幸福的权利；然而在1787年费城制宪会议上，为了换取南方蓄奴各州加入美利坚合众国联邦，开国元勋们达成了著名的‘五分之三妥协’（Three-Fifths Compromise），规定在按人口分配众议院席位和选举人票时，每名黑奴按五分之三自由人折算。这一妥协虽然在脆弱的建国初生期保全了联邦统一，却让奴隶制深深嵌入了美国的政治与经济基石，最终在八十年后酿成南北内战。",
        "coreFigures": "乔治·华盛顿（George Washington）：美利坚合众国首任总统、大陆军总司令，名下拥有弗农山庄数百黑奴，晚年在遗嘱中释放所有奴隶；托马斯·杰斐逊（Thomas Jefferson）：《独立宣言》主要起草人、第三任总统，通过1803年路易斯安那购地案扩大了蓄奴州版图，与黑奴萨莉·海明斯（Sally Hemings）育有多名私生子；亨利·温切克（Henry Wiencek）：著名历史传记作家，《不完美的神》（An Imperfect God）作者，深入挖掘了开国领袖在道德与制度之间的纠葛。",
        "historiographicalTurn": "20世纪70年代以来，史学界兴起‘自下而上’（from the bottom up）的新社会史与微观史学范式，突破了将华盛顿、杰斐逊等建国元勋奉为‘砍樱桃树从不撒谎’的超人神话叙事。结合现代分子生物学DNA证据对私生活与血缘关系的实证检验，现代史学将开国一代放置在历史的具体局限与制度脆弱性中，还原了其既深怀理性启蒙理念、又在经济利益与权力斗争中不断妥协妥协再妥协的复杂人性。"
